/**
 * Single source of truth for the public site's static imagery.
 *
 * - `plate.front` is the one retired plate-era PRODUCT RENDER still shown
 *   (historical pages of the athlete area), generated by tools/renders
 *   (node tools/renders/build.mjs).
 * - `photo.*` are the real photographs that ship with the project.
 *
 * To replace any of them with a final photograph, drop the new WebP files
 * at the same paths (or change the paths here) — no Vue changes needed.
 * Pending photography is listed with exact prompts in PROMPTS-IMAGES.md.
 *
 * Every `alt` is a Spanish literal marked with `t()`; the consumer
 * translates it at render: `:alt="$t(MEDIA.photo.dawn.alt)"`.
 */

/** Marks a Spanish literal for the i18n extractor; consumers translate at render with $t(). */
const t = (text: string): string => text;

export type MediaImage = {
    src: string;
    srcset?: string;
    width: number;
    height: number;
    alt: string;
};

const plate = (
    name: string,
    widths: number[],
    ratio: number,
    alt: string,
): MediaImage => {
    const largest = Math.max(...widths);

    return {
        src: `/media/brand/plate/legacy-plate-${name}-${largest}.webp`,
        srcset: widths
            .map(
                (w) =>
                    `/media/brand/plate/legacy-plate-${name}-${w}.webp ${w}w`,
            )
            .join(', '),
        width: largest,
        height: Math.round(largest / ratio),
        alt,
    };
};

